import React, { useState } from 'react';

const SelfAssessment = () => {
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [answers, setAnswers] = useState({});

  // Sample assessment questions - replace with actual questions
  const questions = [
    {
      id: 1,
      text: "Over the last 2 weeks, how often have you felt down, depressed, or hopeless?",
      options: [
        { value: 0, text: "Not at all" },
        { value: 1, text: "Several days" },
        { value: 2, text: "More than half the days" },
        { value: 3, text: "Nearly every day" }
      ]
    },
    // Add more questions
  ];

  const handleAnswer = (value) => {
    setAnswers({ ...answers, [currentQuestion]: value });
    if (currentQuestion < questions.length - 1) {
      setCurrentQuestion(currentQuestion + 1);
    }
  };

  const calculateResults = () => {
    // Implement scoring logic
    return {
      score: Object.values(answers).reduce((a, b) => a + b, 0),
      maxScore: questions.length * 3
    };
  };

  return (
    <div className="min-h-screen p-6 bg-gray-50 dark:bg-gray-900">
      <h1 className="text-3xl font-bold mb-8 text-gray-800 dark:text-white">
        Mental Health Self-Assessment
      </h1>

      {currentQuestion < questions.length ? (
        <div className="max-w-2xl mx-auto">
          {/* Progress Bar */}
          <div className="mb-8">
            <div className="h-2 w-full bg-gray-200 dark:bg-gray-700 rounded-full">
              <div
                className="h-full bg-blue-600 rounded-full transition-all duration-300"
                style={{
                  width: `${((currentQuestion + 1) / questions.length) * 100}%`
                }}
              />
            </div>
            <div className="text-right text-sm text-gray-600 dark:text-gray-400 mt-2">
              Question {currentQuestion + 1} of {questions.length}
            </div>
          </div>

          {/* Question Card */}
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
            <h2 className="text-xl font-semibold text-gray-800 dark:text-white mb-6">
              {questions[currentQuestion].text}
            </h2>
            <div className="space-y-4">
              {questions[currentQuestion].options.map((option) => (
                <button
                  key={option.value}
                  onClick={() => handleAnswer(option.value)}
                  className="w-full p-4 text-left bg-gray-50 dark:bg-gray-700 
                           rounded-lg border border-gray-200 dark:border-gray-600
                           hover:bg-gray-100 dark:hover:bg-gray-600 transition-colors
                           text-gray-800 dark:text-white"
                >
                  {option.text}
                </button>
              ))}
            </div>
          </div>
        </div>
      ) : (
        <div className="max-w-2xl mx-auto">
          {/* Results Card */}
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow-md p-6">
            <h2 className="text-2xl font-semibold text-gray-800 dark:text-white mb-6">
              Assessment Results
            </h2>
            <div className="mb-6">
              <div className="text-4xl font-bold text-blue-600 dark:text-blue-400 mb-2">
                {calculateResults().score} / {calculateResults().maxScore}
              </div>
              <p className="text-gray-600 dark:text-gray-300">
                Based on your responses, here are some personalized recommendations:
              </p>
            </div>
            <div className="space-y-4">
              <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
                <h3 className="font-semibold text-blue-800 dark:text-blue-400 mb-2">
                  Suggested Actions
                </h3>
                <ul className="list-disc list-inside text-gray-700 dark:text-gray-300">
                  <li>Schedule a consultation with a mental health professional</li>
                  <li>Try our guided meditation sessions</li>
                  <li>Join our virtual support community</li>
                </ul>
              </div>
              <button
                onClick={() => setCurrentQuestion(0)}
                className="w-full p-3 bg-blue-600 text-white rounded-lg
                         hover:bg-blue-700 transition-colors"
              >
                Take Assessment Again
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SelfAssessment;
